from pathlib import Path
import argparse,shutil
import pandas as pd,numpy as np
from select_onoff_stars import paired
from nba_api.stats.static import teams

def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument('--output-dir',type=Path,default=Path(__file__).resolve().parent/'nba_passing_output');p.add_argument('--data-dir',type=Path);a=p.parse_args(argv);root=a.output_dir;out=a.data_dir or root/'creator_dependency';out.mkdir(parents=True,exist_ok=True);metrics=pd.read_csv(root/'court_zone_networks/regressions/four_metrics.csv');metrics=metrics[metrics.season.eq('2024-25')].set_index('team');players=pd.read_csv(root/'2025-26/team_season_topics/player_games.csv',dtype={'GAME_ID':str});games=pd.read_csv(root/'2025-26/team_season_topics/team_games.csv',dtype={'GAME_ID':str});games['date']=pd.to_datetime(games.GAME_DATE);coverage=[];rows=[];rankings=[]
 for t in teams.get_teams():
  team=t['abbreviation'];tid=t['id'];f=pd.read_csv(out/'tracking_2024-25'/(team+'.csv'));f['potential_assists_per36']=np.divide(36*f.POTENTIAL_AST,f.MIN,out=np.zeros(len(f)),where=f.MIN>0);f['eligible_minutes']=f.MIN.ge(1000);f['team']=team;f['eligible_rank']=np.nan;eligible=f[f.eligible_minutes].sort_values(['potential_assists_per36','PLAYER_ID'],ascending=[False,True]);assert len(eligible)>0,team;f.loc[eligible.index,'eligible_rank']=range(1,len(eligible)+1);rankings.append(f);leader=eligible.iloc[0];pid=int(leader.PLAYER_ID);player_name=leader.PLAYER_NAME;potential_assists=float(leader.POTENTIAL_AST);tracking_minutes=float(leader.MIN);rate=float(leader.potential_assists_per36)
  g=games[games.TEAM_ID.eq(tid)].sort_values(['date','GAME_ID']);early=set(g.head(10).GAME_ID);part=players[players.TEAM_ID.eq(tid)&players.PLAYER_ID.eq(pid)];retained=part.GAME_ID.isin(early).any();c=dict(team=team,star_id=pid,star_name=player_name,prior_potential_assists=potential_assists,prior_tracking_minutes=tracking_minutes,prior_potential_assists_per36=rate,retained_first10=bool(retained),status='not_retained_first10')
  if not retained:coverage.append(c);continue
  other=players[players.PLAYER_ID.eq(pid)&players.TEAM_ID.ne(tid)];date=pd.to_datetime(other.GAME_DATE).min() if len(other) else pd.NaT;censor=date-pd.Timedelta(days=14) if pd.notna(date) else pd.NaT;window=g[g.date.lt(censor)] if pd.notna(censor) else g;played=set(part.GAME_ID);ngp=int(window.GAME_ID.isin(played).sum());absent=len(window)-ngp;c.update(present_games=ngp,absent_games=absent,status='available' if absent else 'no_observed_absence');coverage.append(c)
  if not absent:continue
  prior=paired(root/'onoff_dependency/onoff/2024-25'/(team+'.csv'));q=prior[prior.VS_PLAYER_ID.eq(pid)];assert len(q)==1;prior=q.iloc[0];cur=paired(root/'onoff_dependency/onoff/2025-26'/(team+'.csv'));cur=cur[cur.VS_PLAYER_ID.eq(pid)];assert len(cur)==1;cur=cur.iloc[0]
  rows.append(dict(team=team,team_id=tid,star_id=pid,star_name=player_name,prior_on_off_gap=prior.OFF_RATING_on-prior.OFF_RATING_off,prior_on_ortg=prior.OFF_RATING_on,prior_off_ortg=prior.OFF_RATING_off,prior_on_minutes=prior.MIN_on,prior_off_minutes=prior.MIN_off,current_on_off_gap=cur.OFF_RATING_on-cur.OFF_RATING_off,current_on_ortg=cur.OFF_RATING_on,current_off_ortg=cur.OFF_RATING_off,present_games=ngp,absent_games=absent,window_games=len(window),window_start=window.date.min().date().isoformat(),window_end=window.date.max().date().isoformat(),trade_censor_date=str(censor.date()) if pd.notna(censor) else '',first_other_team_date=str(date.date()) if pd.notna(date) else '',star_selection='Primary creator: highest 2024-25 potential assists per36 among players with at least 1000 tracked minutes; no substitute chosen',prior_potential_assists=potential_assists,prior_tracking_minutes=tracking_minutes,prior_potential_assists_per36=rate))
 pd.concat(rankings).to_csv(out/'all_creator_candidates.csv',index=False);pd.DataFrame(coverage).sort_values('team').to_csv(out/'coverage_all_30.csv',index=False);d=pd.DataFrame(rows).sort_values(['prior_on_off_gap','team'],ascending=[False,True]);d.insert(0,'dependency_rank',range(1,len(d)+1));d.to_csv(out/'selected_stars.csv',index=False);print(d[['team','star_name','prior_on_off_gap','present_games','absent_games','window_games']].to_string(index=False));print(pd.DataFrame(coverage).status.value_counts().to_string())
if __name__=='__main__':main()
